<?php declare(strict_types=1);namespace App\Interface\Http\Arena\Controller;use App\Application\Arena\Service\CloseDuelRoundService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Arena\ArenaRealtimePublisher;use App\Infrastructure\Http\ApiResponseFactory;use App\Interface\Http\Identity\IdentityRequestFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;final class ArenaRoundController{public function __construct(private readonly AuthService $auth,private readonly CloseDuelRoundService $service,private readonly ArenaRealtimePublisher $publisher,private readonly ApiResponseFactory $responses){}public function close(ServerRequestInterface $r,ResponseInterface $s,string $id):ResponseInterface{try{$u=$this->auth->currentUser((new IdentityRequestFactory())->accessToken($r));$closed=$this->service->close($id,$u->id);if($closed)$this->publisher->publish($id);return$this->responses->success($s,['closed'=>$closed],(string)$r->getAttribute('request_id'));}catch(\Throwable){return$this->responses->problem($s,'STATE_CONFLICT','A rodada não pode ser encerrada.',409,(string)$r->getAttribute('request_id'));}}}
